import{_ as r,c as s,o as a,ah as t,j as e,a as i}from"./chunks/framework.CDiWxQbG.js";const l="/Qonnectra-docs/pr-18/images/manual/teil-a/settings.jpg",d="/Qonnectra-docs/pr-18/images/manual/teil-a/settings_sync.jpg",o="/Qonnectra-docs/pr-18/images/manual/teil-a/settings_sidebar.jpg",h="/Qonnectra-docs/pr-18/images/manual/teil-a/settings_trench_style.jpg",u="/Qonnectra-docs/pr-18/images/manual/teil-a/settings_node_types.jpg",c="/Qonnectra-docs/pr-18/videos/settings_style_reset.webm",g="/Qonnectra-docs/pr-18/images/manual/teil-a/settings_cable_routing.jpg",S=JSON.parse('{"title":"17. Einstellungen","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/17-einstellungen.md","filePath":"manual/teil-a-anwenderhandbuch/17-einstellungen.md"}'),b={name:"manual/teil-a-anwenderhandbuch/17-einstellungen.md"};function m(p,n,f,k,z,_){return a(),s("div",null,[...n[0]||(n[0]=[t('<h1 id="_17-einstellungen" tabindex="-1">17. Einstellungen <a class="header-anchor" href="#_17-einstellungen" aria-label="Permalink to &quot;17. Einstellungen&quot;">​</a></h1><p>Die <strong>Einstellungen</strong> sammeln, was Sie persönlich an Qonnectra einstellen können: die Angaben zu Ihrem Konto, die Breite der Navigationsleiste, die Farben und Formen der Kartenobjekte, die Farbe der Kabel im Netzschema und die Toleranz des Routings in der Rohrzuordnung. Sie erreichen sie über die linke Navigationsleiste im Fußbereich „System“ durch Klicken auf den Menüpunkt „Einstellungen“.</p><p><img src="'+l+'" alt="Screenshot der Einstellungen mit den Abschnitten „Benutzer“, „UI“ und dem Beginn des Abschnitts „Karte“" data-zoomable="true"></p><p>Alles auf dieser Seite wirkt sofort und nur für Sie: Es gibt keinen „Speichern“-Button, und niemand sonst bekommt Ihre Farben zu sehen. Umgekehrt ändert nichts davon die Daten – nur, wie sie dargestellt werden.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die Einstellungen liegen zunächst im Browser, mit dem Sie sie vorgenommen haben. An einem anderen Rechner, in einem anderen Browser oder nach dem Löschen der Browserdaten sind sie wieder auf den Ausgangswerten. Damit sie Ihnen folgen, speichern Sie sie in Ihrem Konto, siehe Abschnitt <a href="#_17-2-einstellungen-im-konto-speichern-und-wieder-laden">Einstellungen im Konto speichern und wieder laden</a>.</p></div><h2 id="_17-1-benutzerkonto" tabindex="-1">17.1 Benutzerkonto <a class="header-anchor" href="#_17-1-benutzerkonto" aria-label="Permalink to &quot;17.1 Benutzerkonto&quot;">​</a></h2><p>Der Abschnitt „Benutzer“ nennt den „Benutzernamen“ und die „E-Mail“ des angemeldeten Kontos. Beide Angaben lassen sich hier nur ablesen. Stimmt etwas davon nicht, ändert das Ihre Administration im Administrationsbereich, siehe Kapitel <a href="./../teil-b-betrieb-admin-qgis/20-administrationsbereich.html">Der Administrationsbereich</a>.</p><p>Ein Feld zum Ändern des Passworts gibt es nicht; auch das übernimmt die Administration, siehe Abschnitt <a href="./01-erste-schritte.html#_1-1-2-passwort-vergessen">Passwort vergessen?</a>.</p><h2 id="_17-2-einstellungen-im-konto-speichern-und-wieder-laden" tabindex="-1">17.2 Einstellungen im Konto speichern und wieder laden <a class="header-anchor" href="#_17-2-einstellungen-im-konto-speichern-und-wieder-laden" aria-label="Permalink to &quot;17.2 Einstellungen im Konto speichern und wieder laden&quot;">​</a></h2><p>Unter „Einstellungen synchronisieren“ stehen zwei Schaltflächen: „In Konto speichern“ legt Ihre aktuellen Einstellungen in Ihrem Benutzerkonto ab, „Aus Konto laden“ holt sie von dort in den gerade benutzten Browser und lädt die Seite anschließend neu.</p><p><img src="'+d+'" alt="Screenshot der Einstellungen mit Hervorhebung des Bereichs „Einstellungen synchronisieren“ mit den Schaltflächen „In Konto speichern“ und „Aus Konto laden“" data-zoomable="true"></p><p>Gespeichert wird dabei mehr als diese Seite: Qonnectra nimmt alle persönlichen Voreinstellungen mit, die es im Browser ablegt. Dazu gehören</p><ul><li>die Navigationsleiste mit ihren zugeklappten Gruppen und ausgeblendeten Einträgen, siehe Abschnitt <a href="./01-erste-schritte.html#_1-5-navigationsleiste-anpassen">Navigationsleiste anpassen</a>,</li><li>der Hell- und Dunkelmodus samt der Darstellung der Hintergrundkarte, siehe Abschnitt <a href="./01-erste-schritte.html#_1-4-sprache-hell-und-dunkelmodus-versionsanzeige-und-dokumentation">Sprache, Hell- und Dunkelmodus</a>,</li><li>alle Farben und Formen aus den Abschnitten <a href="#_17-4-kartendarstellung-trassenfarbe-trassen-darstellung-highlight-farbe">Kartendarstellung</a> und <a href="#_17-5-stile-fur-netzknotentypen-adressen-und-gebietstypen">Stile</a>,</li><li>die Legende der Karte: ein- und ausgeblendete Layer, Beschriftungen und die Transparenz der Hintergrundkarte, siehe Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-3-das-kartenfenster">Das Kartenfenster</a>,</li><li>die Breite der Info-Box, siehe Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-6-die-info-box-mit-ihren-reitern">Die Info-Box</a>,</li><li>das gewählte Kennzeichen als projektweiter Filter, siehe Abschnitt <a href="./02-grundbegriffe-und-datenmodell.html#_2-6-kennzeichen-als-projektweiter-filter">Kennzeichen</a>,</li><li>die Schaltfläche „Alle Projekte anzeigen“ der Karte,</li><li>der Routing-Modus und die Anzeigeoptionen der Rohrzuordnung, siehe Kapitel <a href="./11-rohrzuordnung.html">Rohrzuordnung</a>,</li><li>die Anzeigeoptionen des Netzschemas, darunter „Einrasten“ und die Kabelfarbe, siehe Abschnitt <a href="./14-netzschema.html#_14-10-anzeigeoptionen-einrasten-kabelrichtungs-animation">Anzeigeoptionen</a>.</li></ul><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Beides sind einmalige Vorgänge, keine laufende Synchronisierung: Qonnectra gleicht nichts von selbst ab. Was Sie nach dem Speichern noch ändern, bleibt in diesem Browser, bis Sie erneut auf „In Konto speichern“ klicken – und ein anderer Rechner sieht Ihre Änderungen erst, wenn Sie dort „Aus Konto laden“ klicken.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Nicht mitgenommen werden die Sprache der Oberfläche, der zuletzt betrachtete Kartenausschnitt und das ausgewählte Projekt. Sprache und Projekt stellen Sie in der Kopfzeile jedes Mal neu ein, siehe Abschnitt <a href="./01-erste-schritte.html#_1-2-aufbau-der-oberflache">Aufbau der Oberfläche</a>.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Es gibt genau einen Speicherstand je Konto, und „In Konto speichern“ überschreibt ihn ohne Rückfrage. Wer an zwei Rechnern arbeitet, sollte deshalb immer in derselben Richtung arbeiten: an dem einen speichern, an dem anderen laden. Speichern Sie von beiden aus, gewinnt der zuletzt gespeicherte Stand.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>„Aus Konto laden“ überschreibt umgekehrt die Einstellungen des Browsers, in dem Sie es klicken. Ein Hinweis erscheint vorher nicht; die Seite lädt sich sofort danach neu.</p></div><h2 id="_17-3-oberflache-seitenleiste-und-theme" tabindex="-1">17.3 Oberfläche: Seitenleiste und Theme <a class="header-anchor" href="#_17-3-oberflache-seitenleiste-und-theme" aria-label="Permalink to &quot;17.3 Oberfläche: Seitenleiste und Theme&quot;">​</a></h2><p>Der Abschnitt „UI“ enthält einen einzigen Schalter, „Sidebar“. Er bestimmt, wie breit die Navigationsleiste am linken Rand ist: <strong>„Erweitert“</strong> – die Voreinstellung – zeigt sie mit Gruppennamen und Beschriftungen, <strong>„Eingeklappt“</strong> verkleinert sie auf eine schmale Leiste mit den Symbolen allein. Der Menüpunkt, auf dem Sie gerade stehen, bleibt auch dann hervorgehoben; die Beschriftung erscheint beim Zeigen mit der Maus.</p><p><img src="'+o+'" alt="Screenshot der Einstellungen mit eingeklappter Navigationsleiste und Hervorhebung des Schalters „Sidebar“" data-zoomable="true"></p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Diesen Schalter gibt es nur hier. In der Navigationsleiste selbst können Sie Gruppen zuklappen und einzelne Einträge ausblenden, sie aber nicht auf Symbole verkleinern, siehe Abschnitt <a href="./01-erste-schritte.html#_1-5-navigationsleiste-anpassen">Navigationsleiste anpassen</a>.</p></div><p>Die Umschaltung zwischen Hell- und Dunkelmodus steht nicht in den Einstellungen, sondern als Symbol in der Kopfzeile, siehe Abschnitt <a href="./01-erste-schritte.html#_1-4-sprache-hell-und-dunkelmodus-versionsanzeige-und-dokumentation">Sprache, Hell- und Dunkelmodus, Versionsanzeige und Dokumentation</a>. Zu den Angaben, die in Ihr Konto übertragen werden, gehört sie trotzdem.</p><h2 id="_17-4-kartendarstellung-trassenfarbe-trassen-darstellung-highlight-farbe" tabindex="-1">17.4 Kartendarstellung: Trassenfarbe, Trassen-Darstellung, Highlight-Farbe <a class="header-anchor" href="#_17-4-kartendarstellung-trassenfarbe-trassen-darstellung-highlight-farbe" aria-label="Permalink to &quot;17.4 Kartendarstellung: Trassenfarbe, Trassen-Darstellung, Highlight-Farbe&quot;">​</a></h2><p>Der Abschnitt „Karte“ beginnt mit drei Einstellungen, die für alle Kartenfenster gelten – auch für die verkleinerten in der Nachverdichtung und in den Adressdetails.</p><p><strong>„Featurefarbe Highlight“</strong> ist die Farbe, in der ein angeklicktes Objekt in der Karte erscheint. Voreingestellt ist Gelb.</p><p><strong>„Trassenfarbe“</strong> ist die Farbe aller Trassenlinien, voreingestellt Blau.</p><p><strong>„Trassen-Darstellung“</strong> entscheidet, ob es bei dieser einen Farbe bleibt:</p><ul><li><strong>„Einzelne Farbe“</strong> – alle Trassen in der Farbe aus „Trassenfarbe“. Die Voreinstellung.</li><li><strong>„Nach Oberfläche“</strong> – je Oberfläche eine eigene Farbe.</li><li><strong>„Nach Bauart“</strong> – je Bauart eine eigene Farbe.</li></ul><p>Bei den beiden letzten erscheint darunter ein weiterer Abschnitt, „Oberflächen-Stile“ bzw. „Bauart-Stile“, mit einer Kachel je Wert aus den Stammdaten. Alle beginnen bei der Trassenfarbe; ordnen Sie den Werten dort unterschiedliche Farben zu.</p><p><img src="'+h+'" alt="Screenshot der Einstellungen mit der Trassen-Darstellung „Nach Oberfläche“ und den darunter erschienenen „Oberflächen-Stilen“" data-zoomable="true"></p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Dieselbe Umstellung entscheidet auch darüber, ob sich der Eintrag „Trasse“ in der Legende der Karte aufklappen lässt. Erst „Nach Oberfläche“ oder „Nach Bauart“ macht die einzelnen Oberflächen und Bauarten dort getrennt schaltbar, siehe Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-3-das-kartenfenster">Das Kartenfenster</a>.</p></div><p>Ein Klick auf das Farbfeld öffnet die Farbauswahl Ihres Betriebssystems. „Zurücksetzen“ rechts neben „Featurefarbe Highlight“ und „Trassenfarbe“ stellt den Ausgangswert wieder her.</p><h2 id="_17-5-stile-fur-netzknotentypen-adressen-und-gebietstypen" tabindex="-1">17.5 Stile für Netzknotentypen, Adressen und Gebietstypen <a class="header-anchor" href="#_17-5-stile-fur-netzknotentypen-adressen-und-gebietstypen" aria-label="Permalink to &quot;17.5 Stile für Netzknotentypen, Adressen und Gebietstypen&quot;">​</a></h2><p>Die drei folgenden Abschnitte arbeiten gleich: Jeder zeigt eine Kachel je Eintrag mit einer Vorschau und darunter den einstellbaren Werten.</p><p><strong>„Netzknotentyp-Stile“</strong> – je Netzknotentyp „Farbe“, „Größe“ (3 bis 30) und „Form“ („Quadrat“ oder „Kreis“).</p><p><img src="'+u+'" alt="Screenshot der Einstellungen mit dem Abschnitt „Netzknotentyp-Stile“ und den Kacheln der einzelnen Netzknotentypen" data-zoomable="true"></p><p><strong>„Adressen-Stil“</strong> – eine einzige Kachel, „Adressenpunkte“, mit „Farbe“ und „Größe“ für alle Adressen zusammen.</p><p><strong>„Gebietstyp-Stile“</strong> – je Gebietstyp nur die „Farbe“; Gebiete sind Flächen und haben keine Größe.</p><p>Über jedem der drei Abschnitte stehen zwei Schaltflächen: <strong>„Zufällig“</strong> würfelt für alle Kacheln des Abschnitts neue Werte aus – die Farbe und, wo es sie gibt, auch die Größe. Das hilft, Typen auseinanderzuhalten, die in der Karte derzeit gleich aussehen. <strong>„Alle zurücksetzen“</strong> stellt die Ausgangswerte wieder her. Beim Adressen-Stil heißt die zweite Schaltfläche „Zurücksetzen“, weil es dort nur eine Kachel gibt.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Jede Kachel lässt sich auch einzeln zurücksetzen. Die Schaltfläche dafür sitzt oben rechts in der Kachel, ist aber unsichtbar, solange Sie nicht mit der Maus auf die Kachel zeigen – erst dann blendet sie sich ein. Sie heißt „Zurücksetzen“, mit einer Ausnahme: In den „Oberflächen-Stilen“ steht dort unübersetzt „Reset“. Diesen Abschnitt sehen Sie nur, wenn die „Trassen-Darstellung“ auf „Nach Oberfläche“ steht, siehe Abschnitt <a href="#_17-4-kartendarstellung-trassenfarbe-trassen-darstellung-highlight-farbe">Kartendarstellung</a>.</p></div>',40),e("p",null,[e("video",{src:c,controls:"",playsinline:"",preload:"metadata"},[i(" Ihr Browser unterstützt das Abspielen von HTML5-Videos nicht. Sie können die Datei "),e("a",{href:"/videos/settings_style_reset.webm",download:""},"herunterladen"),i(" anstelle des Videos. ")])],-1),t('<div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Neue Netzknotentypen und Gebietstypen, die Ihre Administration anlegt, erscheinen hier von selbst und bringen eine Standardfarbe mit. Die Werte kommen aus den Stammdaten, siehe Abschnitt <a href="./02-grundbegriffe-und-datenmodell.html#_2-7-stammdaten-status-phase-netzebene-firmen">Stammdaten</a>.</p></div><p>Ob ein Typ in der Karte überhaupt gezeichnet wird, stellen Sie nicht hier, sondern in der Legende des Kartenfensters ein.</p><h2 id="_17-6-kabelfarben" tabindex="-1">17.6 Kabelfarben <a class="header-anchor" href="#_17-6-kabelfarben" aria-label="Permalink to &quot;17.6 Kabelfarben&quot;">​</a></h2><p>Der Abschnitt „Kabelfarbe“ betrifft allein das Netzschema. Der „Farbmodus“ bestimmt, wonach sich die Farbe einer Kabellinie richtet:</p><ul><li><strong>„Standard (Grün)“</strong> – alle Kabel grün, unabhängig von allem anderen.</li><li><strong>„Verknüpfungsanzeige (Grün/Blau)“</strong> – <strong>blau</strong>, sobald das Kabel mit mindestens einem Mikrorohr verknüpft ist, und <strong>grün</strong>, solange es mit keinem verknüpft ist. Grün ist hier also das Warnsignal: Diese Kabel liegen in keinem dokumentierten Rohr.</li><li><strong>„Mikrorohrfarbe“</strong> – die Farbe des Mikrorohrs mit der niedrigsten Nummer, mit dem das Kabel verknüpft ist. Die Voreinstellung.</li></ul><p><img src="'+g+'" alt="Screenshot der Einstellungen mit den Abschnitten „Kabelfarbe“ und „Rohrzuordnung“" data-zoomable="true"></p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Grün hat in zwei Modi eine andere Bedeutung: In „Standard (Grün)“ sind alle Kabel grün, in „Mikrorohrfarbe“ dagegen nur die, für die keine Farbe zu ermitteln ist – ein Kabel ohne Verknüpfung oder mit einem Mikrorohr ohne hinterlegte Farbe. Aus der Farbe allein lässt sich der Zustand eines Kabels also nur ablesen, wenn Sie wissen, welcher Modus eingestellt ist.</p></div><p>Verknüpft werden Kabel und Mikrorohr im Netzschema, siehe Abschnitt <a href="./14-netzschema.html#_14-5-kabel-mit-mikrorohren-verknupfen">Kabel mit Mikrorohren verknüpfen</a>.</p><h2 id="_17-7-rohrzuordnung-routing-toleranz" tabindex="-1">17.7 Rohrzuordnung: Routing-Toleranz <a class="header-anchor" href="#_17-7-rohrzuordnung-routing-toleranz" aria-label="Permalink to &quot;17.7 Rohrzuordnung: Routing-Toleranz&quot;">​</a></h2><p>Der Abschnitt „Rohrzuordnung“ enthält den Regler „Routing-Toleranz“ mit den Stufen 1 bis 10, voreingestellt 1.</p><p>Beim Routing sucht Qonnectra einen Weg durch das Trassennetz und muss dazu entscheiden, welche Trassen aneinanderstoßen. Dafür legt es ein Raster über das Projekt und rundet jeden Trassenendpunkt auf die nächste Rasterlinie; Endpunkte, die danach übereinanderliegen, gelten als derselbe Punkt. Die Toleranz ist die Maschenweite dieses Rasters in Metern. Wie Sie den Routing-Modus verwenden, beschreibt Abschnitt <a href="./11-rohrzuordnung.html#_11-4-routing-toleranz-richtig-wahlen">Routing-Toleranz richtig wählen</a>.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Eine hohe Toleranz hilft bei ungenau erfassten Trassen, verbindet aber auch Trassen, die im Gelände nichts miteinander zu tun haben – etwa zwei auf gegenüberliegenden Straßenseiten. Der berechnete Weg ist dann kürzer, als er sein dürfte. Erhöhen Sie den Wert deshalb schrittweise und nur so weit, bis das Routing zustande kommt.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Weil gerundet und nicht gemessen wird, ist die Toleranz keine Garantie: Zwei Endpunkte, die knapp beieinander, aber beiderseits einer Rasterlinie liegen, bleiben getrennt. Eine Lücke, die sich bei Stufe 2 nicht schließt, kann bei Stufe 3 verschwinden – oder erst bei 4.</p></div>',13)])])}const A=r(b,[["render",m]]);export{S as __pageData,A as default};
